#!/usr/bin/env python3
"""What a note smells of: docs/data/notes2.json

The catalogue names about two thousand notes and nobody can hand-write a line for each, so a note is explained in three steps:
  1. exact:   a sentence written for that very name (the commonest notes, and the odd ones a rule would get wrong);
  2. heads:   the material the name is about. Names are head-final in both languages ("Tunisian Orange Blossom",
              "Sicilya limonu"), so of all materials found in a name the rightmost one wins; "generic" heads (flower, wood,
              fruit ...) are asked only when no material was found;
  3. quals / origins: what is left of the name adds a short clause ("candied", "leaf", "white", "Sicilian").

Patterns are matched against the folded name (ASCII, lower case, punctuation as spaces). In a pattern "a|b c|d+" each
alternative is a whole word or phrase; English words may take a plural s, a trailing + lets Turkish endings follow
(limon+ matches limon, limonu, limonlar), a leading = allows nothing after it, a leading ^ matches only when the
alternative is the whole name ("Milk" is milk, "Almond Milk" is almond).

Run:  python scripts/build_notes.py      then  node scripts/notes_check.js  to see what is still unexplained.
"""
import json, os, re

ROOT = os.path.join(os.path.dirname(os.path.abspath(__file__)), '..')
OUT = os.path.join(ROOT, 'docs', 'data', 'notes2.json')
OLD = os.path.join(ROOT, 'docs', 'data', 'notes.json')

TR_END = r'(?:lari|leri|lar|ler|si|su|ni|nu|yi|yu|i|u)?'


def rx(spec):
    alts = []
    for a in spec.split('|'):
        a = a.strip()
        if not a: continue
        whole = a.startswith('^')
        if whole: a = a[1:]
        if a.startswith('='): body, tail = a[1:], ''
        elif a.endswith('+'): body, tail = a[:-1], TR_END
        else: body, tail = a, '(?:e?s)?'
        w = r'\s+'.join(re.escape(x) for x in body.split()) + tail
        alts.append((len(body), '^' + w + '$' if whole else w))
    # a regex takes the first alternative that fits, so the longer phrase has to stand before the word it starts with
    alts = [x[1] for x in sorted(alts, key=lambda x: -x[0])]
    return r'\b(?:' + '|'.join(alts) + r')\b'


