def main():
    exact = {}
    if os.path.exists(OLD):
        exact.update({k.strip(): v for k, v in json.load(open(OLD, encoding='utf-8')).items()})
    else:
        exact.update(json.load(open(OUT, encoding='utf-8')).get('exact', {}))
    exact.update(EXACT)
    for spec, _ in HEADS + GENERIC + QUALS + ORIGINS: re.compile(rx(spec))
    data = {
        'v': 2,
        'exact': exact,
        'heads': [[rx(s), t] for s, t in HEADS],
        'generic': [[rx(s), t] for s, t in GENERIC],
        'quals': [[rx(s), t] for s, t in QUALS],
        'origins': [[rx(s), t] for s, t in ORIGINS],
        'tm': 'Parfüm evlerine özel bir koku molekülü ya da akor; üreticisinin tescilli adıyla anılır ve tam olarak neye benzediği açıklanmaz.',
        'unknown': 'Bu ad için hazır bir açıklama yok; büyük olasılıkla parfümcünün verdiği özel bir ad. Aşağıdaki parfümlerde nasıl koktuğunu deneyebilirsin.',
    }
    json.dump(data, open(OUT, 'w', encoding='utf-8'), ensure_ascii=False, separators=(',', ':'))
    print(len(exact), 'exact,', len(HEADS), 'heads,', len(GENERIC), 'generic ->', OUT, os.path.getsize(OUT), 'bytes')


if __name__ == '__main__':
    main()
